const normalize = (str) =>
  (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, "");

// Helps compare "Hanya Yanagihara" etc.
const normalizeAuthor = (str) => normalize(str);

return $input.all().map(item => {
  const data = item.json;

  const originalTitle = data.title || "";
  const originalAuthor = data.creator || "";
  const originalYear = Number(data.year);

  const candidates = data.items || [];

  let match = null;
  let matchMethod = "unmatched";

  // 1. Strongest match: title + author + year
  match = candidates.find(book => {
    const info = book.volumeInfo || {};

    const titleMatches =
      normalize(info.title) === normalize(originalTitle);

    const authorMatches =
      (info.authors || []).some(author =>
        normalizeAuthor(author) === normalizeAuthor(originalAuthor)
      );

    const bookYear = info.publishedDate
      ? Number(info.publishedDate.substring(0, 4))
      : null;

    return (
      titleMatches &&
      authorMatches &&
      bookYear === originalYear
    );
  });

  if (match) {
    matchMethod = "title_author_year";
  }

  // 2. Fallback: title + author
  if (!match) {
    match = candidates.find(book => {
      const info = book.volumeInfo || {};

      const titleMatches =
        normalize(info.title) === normalize(originalTitle);

      const authorMatches =
        (info.authors || []).some(author =>
          normalizeAuthor(author) === normalizeAuthor(originalAuthor)
        );

      return titleMatches && authorMatches;
    });

    if (match) {
      matchMethod = "title_author";
    }
  }

  // 3. Last fallback: exact title
  if (!match) {
    match = candidates.find(book => {
      const info = book.volumeInfo || {};

      return normalize(info.title) === normalize(originalTitle);
    });

    if (match) {
      matchMethod = "title_only";
    }
  }

  const info = match?.volumeInfo || {};

  // Extract ISBNs cleanly
  const isbn13 =
    (info.industryIdentifiers || [])
      .find(id => id.type === "ISBN_13")?.identifier ?? null;

  const isbn10 =
    (info.industryIdentifiers || [])
      .find(id => id.type === "ISBN_10")?.identifier ?? null;

  return {
    json: {
      // ORIGINAL GOODREADS DATA
      media_type: data.media_type,
      title: data.title,
      creator: data.creator,
      year: data.year,
      user_rating: data.user_rating,
      rating_scale_max: data.rating_scale_max,
      preference_class: data.preference_class,
      liked: data.liked,
      consumed_date: data.consumed_date,
      source: data.source,
      source_id: data.source_id,

      // MATCH AUDIT
      google_books_match_found: !!match,
      google_books_match_method: matchMethod,

      // GOOGLE BOOKS DATA
      google_books_id: match?.id ?? null,
      google_books_title: info.title ?? null,
      google_books_subtitle: info.subtitle ?? null,
      google_books_authors: info.authors ?? [],
      google_books_published_date: info.publishedDate ?? null,
      google_books_description: info.description ?? null,
      google_books_categories: info.categories ?? [],
      google_books_language: info.language ?? null,
      google_books_page_count: info.pageCount ?? null,
      google_books_average_rating: info.averageRating ?? null,
      google_books_ratings_count: info.ratingsCount ?? null,
      google_books_isbn_13: isbn13,
      google_books_isbn_10: isbn10
    }
  };
});

const normalize = (str) =>
  (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, "");

return $input.all().map(item => {
  const data = item.json;

  const originalTitle = data.title;
  const originalYear = Number(data.year);
  const candidates = data.results || [];

  let match = null;
  let matchMethod = "unmatched";

  // 1. Strong match: title + year
  match = candidates.find(movie => {
    const movieYear = movie.release_date
      ? Number(movie.release_date.substring(0, 4))
      : null;

    return (
      (
        normalize(movie.title) === normalize(originalTitle) ||
        normalize(movie.original_title) === normalize(originalTitle)
      ) &&
      movieYear === originalYear
    );
  });

  if (match) {
    matchMethod = "title_and_year";
  }

  // 2. Fallback: title only
  if (!match) {
    match = candidates.find(movie =>
      normalize(movie.title) === normalize(originalTitle) ||
      normalize(movie.original_title) === normalize(originalTitle)
    );

    if (match) {
      matchMethod = "title_only";
    }
  }

  return {
    json: {
      media_type: data.media_type,
      title: data.title,
      creator: data.creator,
      year: data.year,
      user_rating: data.user_rating,
      rating_scale_max: data.rating_scale_max,
      preference_class: data.preference_class,
      liked: data.liked,
      consumed_date: data.consumed_date,
      source: data.source,
      source_id: data.source_id,

      tmdb_match_found: !!match,
      tmdb_match_method: matchMethod,

      tmdb_id: match?.id ?? null,
      tmdb_title: match?.title ?? null,
      tmdb_original_title: match?.original_title ?? null,
      tmdb_release_date: match?.release_date ?? null,
      tmdb_overview: match?.overview ?? null,
      tmdb_genre_ids: match?.genre_ids ?? [],
      tmdb_original_language: match?.original_language ?? null,
      tmdb_popularity: match?.popularity ?? null,
      tmdb_vote_average: match?.vote_average ?? null,
      tmdb_vote_count: match?.vote_count ?? null
    }
  };
});

const tmdbGenres = {
  28: "Action",
  12: "Adventure",
  16: "Animation",
  35: "Comedy",
  80: "Crime",
  99: "Documentary",
  18: "Drama",
  10751: "Family",
  14: "Fantasy",
  36: "History",
  27: "Horror",
  10402: "Music",
  9648: "Mystery",
  10749: "Romance",
  878: "Science Fiction",
  10770: "TV Movie",
  53: "Thriller",
  10752: "War",
  37: "Western"
};

function isTrue(value) {
  return value === true || String(value).toLowerCase() === "true";
}

return $input.all().map(item => {
  const data = item.json;

  const isFilm = data.media_type === "film";
  const isBook = data.media_type === "book";

  // Standardise genres/categories
  const genres = isFilm
    ? (data.tmdb_genre_ids || []).map(
        id => tmdbGenres[id] || `Unknown (${id})`
      )
    : (data.google_books_categories || []);

  // Standardise description
  const description = isFilm
    ? data.tmdb_overview
    : data.google_books_description;

  // Standardise match status
  const metadataMatchFound = isFilm
    ? isTrue(data.tmdb_match_found)
    : isBook
      ? isTrue(data.google_books_match_found)
      : false;

  const hasDescription =
    typeof description === "string" &&
    description.trim().length >= 20;

  const readyForAI =
    metadataMatchFound && hasDescription;

  return {
    json: {
      ...data,

      ai_genres: genres,
      ai_description: description || null,

      metadata_match_found: metadataMatchFound,
      has_description: hasDescription,
      ready_for_ai: readyForAI
    }
  };
});

// ============================================================
// TASTE MODEL v0.3
// Continuous preference model + Pearson correlation
// ============================================================
//
// MAIN CONCEPTS
//
// prevalence:
//   How present is a semantic characteristic across consumed works?
//
// preference_association:
//   Pearson correlation between semantic presence and the user's
//   rating-derived preference weight.
//
//   Range: -1 to +1
//   Positive = stronger presence tends to accompany higher ratings
//   Negative = stronger presence tends to accompany lower ratings
//   Near 0 = little/no linear relationship
//
// evidence_count:
//   Number of works where the dimension is meaningfully present.
//
// evidence_confidence:
//   POC heuristic describing the amount and diversity of evidence.
//   It is NOT the probability that the inferred preference is true.
//
// ============================================================


const items = $input.all();


// ============================================================
// HELPERS
// ============================================================

function getSemanticData(j) {

  // Expected OpenAI structured output
  let semantic = j.output?.[0]?.content?.[0]?.text;

  // Sometimes structured output may arrive as a JSON string
  if (typeof semantic === 'string') {
    try {
      semantic = JSON.parse(semantic);
    } catch {
      return null;
    }
  }

  // Optional fallback if semantic data was normalized upstream
  if (!semantic && j.semantic && typeof j.semantic === 'object') {
    semantic = j.semantic;
  }

  return semantic && typeof semantic === 'object'
    ? semantic
    : null;
}


function round(value, decimals = 3) {

  if (!Number.isFinite(value)) {
    return null;
  }

  const factor = 10 ** decimals;

  return Math.round(value * factor) / factor;
}


// ============================================================
// PEARSON CORRELATION
// ============================================================
//
// Measures linear association between:
//
// X = semantic score
// Y = preference weight
//
// Returns a value between -1 and +1.
//
// ============================================================

function pearsonCorrelation(xs, ys) {

  if (
    xs.length !== ys.length ||
    xs.length < 2
  ) {
    return 0;
  }

  const n = xs.length;

  const meanX =
    xs.reduce((sum, x) => sum + x, 0) / n;

  const meanY =
    ys.reduce((sum, y) => sum + y, 0) / n;


  let numerator = 0;
  let denominatorX = 0;
  let denominatorY = 0;


  for (let i = 0; i < n; i++) {

    const dx = xs[i] - meanX;
    const dy = ys[i] - meanY;

    numerator += dx * dy;

    denominatorX += dx * dx;
    denominatorY += dy * dy;
  }


  const denominator =
    Math.sqrt(
      denominatorX * denominatorY
    );


  // No variation in one of the variables means
  // correlation is undefined.
  // For the POC we treat this as no usable association.
  if (denominator === 0) {
    return 0;
  }


  return numerator / denominator;
}


// ============================================================
// RATING → PREFERENCE WEIGHT
// ============================================================

const weightMap = {

  5:   1.00,
  4.5: 0.80,
  4:   0.60,
  3.5: 0.25,
  3:   0.00,
  2.5: -0.25,
  2:   -0.60,
  1.5: -0.80,
  1:   -1.00,
  0.5: -1.00

};


// ============================================================
// COLLECT VALID WORKS
// ============================================================

const works = [];


for (const item of items) {

  const j = item.json;

  const semantic =
    getSemanticData(j);


  if (!semantic) {
    continue;
  }


  const rating =
    Number(j.user_rating);


  let preferenceWeight =
    Number(j.preference_weight);


  // Fallback:
  // derive weight directly from rating if the CSV field
  // disappeared somewhere upstream.
  if (!Number.isFinite(preferenceWeight)) {

    preferenceWeight =
      weightMap[rating];

  }


  if (!Number.isFinite(preferenceWeight)) {
    continue;
  }


  works.push({

    title:
      j.title ?? null,

    media_type:
      j.media_type ?? null,

    user_rating:
      Number.isFinite(rating)
        ? rating
        : null,

    preference_weight:
      preferenceWeight,

    semantic:
      semantic

  });

}


// ============================================================
// SAFETY CHECK
// ============================================================

if (works.length === 0) {

  throw new Error(
    'No valid works found. Check semantic output and rating/preference data after Merge3.'
  );

}


// ============================================================
// BUILD DIMENSION LIST
// ============================================================

const dimensionKeys = [];

const firstSemantic =
  works[0].semantic;


for (
  const [group, dimensions]
  of Object.entries(firstSemantic)
) {

  if (
    !dimensions ||
    typeof dimensions !== 'object'
  ) {
    continue;
  }


  for (
    const dimension
    of Object.keys(dimensions)
  ) {

    dimensionKeys.push({
      group,
      dimension
    });

  }

}


// ============================================================
// GLOBAL PREFERENCE STATISTICS
// ============================================================

const meanPreference =
  works.reduce(
    (sum, work) =>
      sum + work.preference_weight,
    0
  ) / works.length;


// ============================================================
// CALCULATE DIMENSION STATISTICS
// ============================================================

const results = [];


for (
  const { group, dimension }
  of dimensionKeys
) {


  // ----------------------------------------------------------
  // Collect observations
  // ----------------------------------------------------------

  const observations =
    works
      .map(work => ({

        semantic_score:
          Number(
            work.semantic?.[group]?.[dimension]
          ),

        preference_weight:
          work.preference_weight,

        media_type:
          work.media_type

      }))
      .filter(obs =>

        Number.isFinite(
          obs.semantic_score
        ) &&

        Number.isFinite(
          obs.preference_weight
        )

      );


  if (observations.length === 0) {
    continue;
  }


  // ==========================================================
  // 1. PREVALENCE
  // ==========================================================

  const prevalence =
    observations.reduce(
      (sum, o) =>
        sum + o.semantic_score,
      0
    ) / observations.length;


  // ==========================================================
  // 2. PREFERENCE ASSOCIATION
  // ==========================================================
  //
  // Pearson correlation:
  //
  // semantic score ↔ preference weight
  //
  // ==========================================================

  const semanticScores =
    observations.map(
      o => o.semantic_score
    );


  const preferenceWeights =
    observations.map(
      o => o.preference_weight
    );


  const preferenceAssociation =
    pearsonCorrelation(
      semanticScores,
      preferenceWeights
    );


  // ==========================================================
  // 3. EVIDENCE COUNT
  // ==========================================================

  const evidenceCount =
    observations.filter(
      o =>
        o.semantic_score >= 0.25
    ).length;


  // ==========================================================
  // 4. MEDIA-SPECIFIC EVIDENCE
  // ==========================================================

  const filmEvidence =
    observations.filter(
      o =>
        o.media_type === 'film' &&
        o.semantic_score >= 0.25
    ).length;


  const bookEvidence =
    observations.filter(
      o =>
        o.media_type === 'book' &&
        o.semantic_score >= 0.25
    ).length;


  // ==========================================================
  // 5. EVIDENCE CONFIDENCE
  // ==========================================================
  //
  // This describes how much useful evidence exists.
  //
  // It does NOT mean:
  // "91% probability that the user likes this."
  //
  // ==========================================================


  // Evidence-volume component.
  //
  // At 30 meaningful works, this component reaches 1.
  const evidenceVolume =
    Math.min(
      evidenceCount / 30,
      1
    );


  // Semantic variation component.
  //
  // If a dimension receives essentially the same score for
  // every work, it is less useful for distinguishing taste.
  const variance =
    observations.reduce(
      (sum, o) =>

        sum +
        Math.pow(
          o.semantic_score -
          prevalence,
          2
        ),

      0
    ) / observations.length;


  const standardDeviation =
    Math.sqrt(variance);


  const variationEvidence =
    Math.min(
      standardDeviation / 0.35,
      1
    );


  const evidenceConfidence =
    (
      evidenceVolume * 0.70
    ) +
    (
      variationEvidence * 0.30
    );


  // ==========================================================
  // 6. CROSS-MEDIA STATUS
  // ==========================================================
  //
  // This is descriptive only.
  //
  // We require evidence from BOTH media types before calling
  // a signal cross-media.
  //
  // ==========================================================

  let evidenceScope = 'limited';


  if (
    filmEvidence >= 3 &&
    bookEvidence >= 3
  ) {

    evidenceScope =
      'cross_media';

  } else if (
    filmEvidence >= 3 &&
    bookEvidence < 3
  ) {

    evidenceScope =
      'film_dominant';

  } else if (
    bookEvidence >= 3 &&
    filmEvidence < 3
  ) {

    evidenceScope =
      'book_dominant';

  }


  // ==========================================================
  // SAVE DIMENSION
  // ==========================================================

  results.push({

    group:
      group,

    dimension:
      dimension,

    prevalence:
      round(prevalence),

    preference_association:
      round(preferenceAssociation),

    evidence_count:
      evidenceCount,

    film_evidence:
      filmEvidence,

    book_evidence:
      bookEvidence,

    evidence_scope:
      evidenceScope,

    evidence_confidence:
      round(evidenceConfidence),

    total_works:
      observations.length

  });

}


// ============================================================
// RANKINGS
// ============================================================


// Strongest positive relationships
const strongestPositive =
  [...results]

    .filter(
      r =>
        r.preference_association > 0
    )

    .sort(
      (a, b) =>
        b.preference_association -
        a.preference_association
    )

    .slice(0, 10);


// Strongest negative relationships
const strongestNegative =
  [...results]

    .filter(
      r =>
        r.preference_association < 0
    )

    .sort(
      (a, b) =>
        a.preference_association -
        b.preference_association
    )

    .slice(0, 10);


// All dimensions ranked by absolute association strength
const strongestSignals =
  [...results]

    .sort(
      (a, b) =>
        Math.abs(
          b.preference_association
        ) -
        Math.abs(
          a.preference_association
        )
    );


// ============================================================
// MEDIA COUNTS
// ============================================================

const filmCount =
  works.filter(
    work =>
      work.media_type === 'film'
  ).length;


const bookCount =
  works.filter(
    work =>
      work.media_type === 'book'
  ).length;


// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {

      model_version:
        'taste_model_v0.3',

      works_analyzed:
        works.length,

      films_analyzed:
        filmCount,

      books_analyzed:
        bookCount,

      dimensions_analyzed:
        results.length,

      mean_preference_weight:
        round(meanPreference),

      methodology: {

        preference_input:
          'Continuous rating-derived preference weight from -1 to +1',

        prevalence:
          'Mean semantic presence across analyzed works',

        preference_association:
          'Pearson correlation between semantic dimension score and rating-derived preference weight',

        evidence_count:
          'Number of works where semantic score >= 0.25',

        evidence_confidence:
          'POC evidence-strength heuristic combining evidence volume (70%) and semantic variation (30%); not a probability or statistical confidence interval',

        evidence_scope:
          'Cross-media when at least 3 films and 3 books provide meaningful evidence'

      },

      strongest_positive_signals:
        strongestPositive,

      strongest_negative_signals:
        strongestNegative,

      all_dimensions:
        strongestSignals

    }
  }
];
